#include <list>
#include <iostream>

int main() {
    std::list<int> l1 = {1, 2, 3};
    std::list<int> l2 = {10, 20, 30};

    // O(1) operation to move all elements from l2 to the end of l1
    // No element copies or moves occur.
    l1.splice(l1.end(), l2);

    // l2 is now empty, l1 contains {1, 2, 3, 10, 20, 30}
    std::cout << "l1 size: " << l1.size() << " l2 size: " << l2.size() << std::endl;
}
